    private static final int BG=Color.rgb(247,249,251), CARD=Color.WHITE, TEXT=Color.rgb(15,20,25), MUTED=Color.rgb(83,100,113), BLUE=Color.rgb(29,155,240), SOFT=Color.rgb(232,240,247), RED=Color.rgb(244,33,46);
